INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_37_m_37_1_121',
  'Order the steps to apply a policy-as-code check using AWS CloudFormation Guard.',
  'ordering',
  '["Run CloudFormation Guard against the template and policy.","Define compliance rules in a CloudFormation Guard policy file.","Prepare an AWS CloudFormation template for validation.","Review the validation report for non-compliant resources."]'::json,
  '{2,1,0,3}',
  'To implement policy-as-code with CloudFormation Guard, you first prepare the AWS CloudFormation template that needs to be validated (Option C). Concurrently, you define your compliance rules in a CloudFormation Guard policy file (Option B). With both the template and policy ready, you then run CloudFormation Guard, specifying both files (Option A). The final step is to review the generated validation report (Option D) to identify any non-compliant resources or configurations.',
  NOW(),
  'quiz_domain37_8',
  NOW(),
  6,
  NULL,
