INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_37_m_37_1_127',
  'A CloudFormation template requires user input for environment-specific configurations. Order the steps to define and reference a parameter within the template.',
