VALUES (
  'q_37_m_37_2_87',
  'Order the steps to integrate AWS CloudFormation Guard into a CI/CD pipeline for policy enforcement.',
  'ordering',
  '["Run CloudFormation Guard validation as a pipeline stage.","Define Guard policies for infrastructure compliance.","Develop AWS CloudFormation templates.","Fail the pipeline if Guard detects non-compliance."]'::json,
