INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_36_m_36_2_63',
  'Which AWS services can be integrated into a CI/CD pipeline to perform various types of automated testing, ensuring code quality and application stability? (Select TWO.)',
  'multiple',
