INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_39_m_39_3_43',
  'Which AWS service provides a serverless event bus that simplifies building event-driven architectures by routing events from various sources to different targets?',
  'mcq',
  '["AWS CloudTrail Lake","Amazon EventBridge","Amazon CloudWatch Logs","AWS X-Ray"]'::json,
  '{1}',
  'Option B (correct) is Amazon EventBridge. It is a serverless event bus that enables you to connect your applications with data from AWS services, your own applications, and SaaS applications. It simplifies event-driven architectures by routing events to various targets based on rules. Option A (incorrect) is AWS CloudTrail Lake, used for auditing API calls. Option C (incorrect) is Amazon CloudWatch Logs, used for collecting and monitoring logs. Option D (incorrect) is AWS X-Ray, used for distributed tracing.',
  NOW(),
  'quiz_domain39_8',
