INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_2_40',
  'Which AWS service provides intelligent threat detection to protect AWS accounts and workloads by continuously monitoring for malicious activity and unauthorized behavior?',
  'mcq',
  '["AWS KMS","Amazon Macie","Amazon GuardDuty","AWS Config"]'::json,
  '{2}',
  'Option C (Amazon GuardDuty) is the correct service for intelligent threat detection, continuously monitoring for malicious activity and unauthorized behavior to protect AWS accounts and workloads. Option A (AWS KMS) manages encryption keys. Option B (Amazon Macie) discovers and protects sensitive data. Option D (AWS Config) monitors resource configurations.',
  NOW(),
  'quiz_domain41_8',
