INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_2_51',
  'A financial institution needs to detect potential threats such as cryptocurrency mining, unauthorized access, and compromised instances within their AWS environment. They require a service that continuously monitors for these activities without requiring agents on their Amazon EC2 instances. Which AWS service should they implement?',
  'mcq',
  '["Amazon Inspector v2","AWS Security Hub","Amazon GuardDuty","AWS Config"]'::json,
  '{2}',
  'Option C (Amazon GuardDuty) is the correct service for this scenario. GuardDuty is a threat detection service that continuously monitors for malicious activity and unauthorized behavior to protect AWS accounts and workloads. It analyzes various data sources, including AWS CloudTrail event logs, Amazon VPC Flow Logs, and DNS logs, without requiring agents. Option A (Amazon Inspector v2) focuses on vulnerability scanning. Option B (AWS Security Hub) aggregates findings but does not perform the direct threat detection. Option D (AWS Config) monitors resource configurations for compliance, not real-time threat detection.',
  NOW(),
  'quiz_domain41_8',
  NOW(),
  14,
  NULL,
  NULL,
  'm_41_2',
  'medium'
);

