INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_2_71',
  'Which AWS services can be used together to automatically remediate non-compliant resource configurations detected by AWS Config? (Select TWO.)',
  'multiple',
