  NULL,
  NULL,
  'm_40_1',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_1_99',
  'Which AWS services are essential for building a robust event-driven architecture that can react to changes across AWS services and custom applications, providing both routing and compute capabilities? (Select TWO.)',
  'multiple',
  '["Amazon SQS (queue, not primary event bus)","Amazon EventBridge","Amazon SNS (notification, not primary event bus)","AWS Lambda","Amazon GuardDuty"]'::json,
  '{1,3}',
  'Option B (Amazon EventBridge) acts as the central event bus, receiving events from various sources, filtering them, and routing them to appropriate targets. Option D (AWS Lambda) provides the serverless compute capability to process these events, executing custom code in response to specific events, which is fundamental to event-driven architectures. Option A (Amazon SQS) is a message queuing service, not an event bus. Option C (Amazon SNS) is a notification service, not the primary event bus for routing. Option E (Amazon GuardDuty) is a threat detection service.',
  NOW(),
  'quiz_domain40_8',
  NOW(),
