INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_1_100',
  'Which AWS services can facilitate cross-account event routing and delivery of events to various AWS targets, enabling centralized event management across an organization? (Select TWO.)',
  'multiple',
