INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_1_101',
  'A DevOps team wants to build an event-driven architecture where specific events from AWS services (e.g., S3 object creation) trigger an AWS Lambda function for processing and also send a notification to stakeholders. Which AWS services are needed? (Select THREE.)',
  'multiple',
