INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_3_57',
  'A company needs to monitor for unauthorized access attempts to their AWS accounts and automatically trigger a notification to the security team. Which AWS services can detect these attempts and send alerts? (Select TWO.)',
