INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_3_62',
  'A DevOps team wants to automatically create operational work items in Systems Manager OpsCenter when a critical application error is detected and reported via a custom event. Which AWS services should they use? (Select TWO.)',
  'multiple',
  '["AWS Config","Amazon GuardDuty","Amazon EventBridge","AWS Lambda (can be triggered, but OpsCenter is for tracking)","AWS Systems Manager OpsCenter"]'::json,
  '{2,4}',
