INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_39_m_39_1_98',
  'Order the steps to configure an Amazon EC2 instance to send application logs to Amazon CloudWatch Logs.',
  'ordering',
  '["Configure the CloudWatch agent to specify log files and destination log groups.","Install the CloudWatch agent on the Amazon EC2 instance.","Create a CloudWatch Logs log group.","Start the CloudWatch agent on the Amazon EC2 instance."]'::json,
  '{2,1,0,3}',
  'To send application logs from an Amazon EC2 instance to Amazon CloudWatch Logs, the logical sequence is to first create the destination log group in CloudWatch Logs (Option C). Next, the CloudWatch agent needs to be installed on the EC2 instance (Option B). After installation, the agent must be configured to specify which log files to collect and which log groups to send them to (Option A). Finally, the CloudWatch agent service needs to be started to begin collecting and sending logs (Option D).',
  NOW(),
  'quiz_domain39_8',
  NOW(),
  1,
  NULL,
  NULL,
  'm_39_1',
  'easy'
