INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_1_124',
  'A security team wants to be immediately notified via email when Amazon GuardDuty detects a high-severity threat. Order the steps to route GuardDuty findings to a notification service with minimal configuration.',
  'ordering',
  '["Create an Amazon EventBridge rule to capture Amazon GuardDuty findings.","Create an Amazon SNS topic for security notifications.","Subscribe the security team''s email address to the SNS topic.","Set the SNS topic as the target for the EventBridge rule."]'::json,
  '{1,2,0,3}',
  'To route GuardDuty findings to a notification service, first, create an Amazon SNS topic (Option B) that will be used for security notifications. Next, subscribe the security team''s email address (Option C) to this SNS topic and ensure the subscription is confirmed. Then, create an Amazon EventBridge rule (Option A) configured to capture Amazon GuardDuty findings, specifically filtering for high-severity threats. Finally, set the SNS topic as the target (Option D) for the EventBridge rule, ensuring that matching GuardDuty findings trigger an email notification.',
