INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_40_m_40_3_64',
  'Arrange the steps to integrate an Amazon CloudWatch alarm with AWS Systems Manager OpsCenter.',
  'ordering',
  '["Configure the CloudWatch alarm to send notifications to an Amazon SNS topic.","Create an Amazon EventBridge rule to trigger an OpsItem from SNS notifications.","Create an Amazon SNS topic.","Verify that OpsItems are created in OpsCenter when the alarm state changes."]'::json,
  '{2,0,1,3}',
  'To integrate a CloudWatch alarm with OpsCenter, you first create an Amazon SNS topic to act as an intermediary for notifications (Option C). Next, you configure your CloudWatch alarm to send notifications to this Amazon SNS topic when its state changes (Option A). Then, you create an Amazon EventBridge rule that listens for messages published to the SNS topic and, upon matching, triggers the creation of an OpsItem in OpsCenter (Option B). Finally, you verify that OpsItems are correctly created in OpsCenter when the CloudWatch alarm transitions to an ALARM state (Option D).',
  NOW(),
  'quiz_domain40_8',
  NOW(),
  64,
  NULL,
  NULL,
  'm_40_3',
  'easy'
);

