INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_2_97',
  'Arrange the steps to automate credential rotation for a database secret using AWS Secrets Manager.',
  'ordering',
  '["Configure the rotation schedule and rotation function in Secrets Manager.","Store the database credentials as a secret in AWS Secrets Manager.","Create an AWS Lambda rotation function that connects to the database.","Grant the Lambda function permissions to access Secrets Manager and the database."]'::json,
  '{1,2,3,0}',
  'The first step is to store the database credentials as a secret in AWS Secrets Manager (Option B). Next, you need to create an AWS Lambda function that contains the logic to rotate the credentials for your specific database (Option C). This Lambda function then needs appropriate IAM permissions to access Secrets Manager and the database itself (Option D). Finally, you configure Secrets Manager to use this Lambda function and define the desired rotation schedule (Option A).',
  NOW(),
  'quiz_domain41_8',
  NOW(),
  2,
  NULL,
  NULL,
  'm_41_2',
  'easy'
