INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_2_98',
  'Place the steps in the correct sequence to enable Amazon GuardDuty for threat detection in your AWS account.',
  'ordering',
  '["Review and manage GuardDuty findings in the console or via API.","Enable GuardDuty in the AWS Management Console or using the AWS CLI.","Configure trusted IP lists and threat lists if needed.","Grant necessary IAM permissions for GuardDuty service-linked role."]'::json,
