);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_2_102',
  'Order the steps to set up cross-account access for a security auditing tool using IAM roles.',
  'ordering',
  '["Configure the auditing tool in the auditor account to assume the role.","Create an IAM role in the target audited account with necessary permissions.","Establish a trust policy on the IAM role allowing the auditor account to assume it.","Grant the IAM user/role in the auditor account permissions to assume the new role."]'::json,
  '{1,2,3,0}',
  'First, create an IAM role in the target audited account that has the necessary permissions for the security auditing tool (Option B). Next, establish a trust policy on this IAM role, explicitly allowing the auditor AWS account to assume it (Option C). Then, in the auditor account, grant the specific IAM user or role that the auditing tool uses permissions to assume the newly created role in the target account (Option D). Finally, configure the auditing tool itself in the auditor account to assume this role when performing its operations (Option A).',
