INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_3_112',
  'After a security incident, a company needs to review and prioritize high-severity security findings to quickly respond and mitigate risks. The security team uses Amazon GuardDuty for threat detection and needs a structured approach to manage its findings. Order the steps to effectively prioritize and respond to high-severity security findings from GuardDuty.',
  'ordering',
  '["Review the high-severity findings generated by Amazon GuardDuty in the AWS Security Hub console or GuardDuty console.","Investigate the details of the high-severity alerts to understand the scope and impact of the potential threat.","Implement immediate containment and remediation actions, such as isolating affected resources or revoking compromised credentials.","Document the incident, apply lessons learned, and enhance existing security controls to prevent recurrence."]'::json,
  '{0,1,2,3}',
  'To prioritize and respond to GuardDuty findings, first review the high-severity findings (Option A) in the Security Hub or GuardDuty console to identify critical threats. Next, investigate the details (Option B) of these alerts to fully understand the scope, affected resources, and potential impact. Then, implement immediate containment and remediation actions (Option C), such as isolating compromised resources or revoking credentials, to mitigate the active threat. Finally, document the incident (Option D), apply lessons learned, and enhance security controls to prevent similar incidents in the future.',
  NOW(),
  'quiz_domain41_8',
  NOW(),
  46,
  NULL,
  NULL,
  'm_41_3',
  'hard'
);

