  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_41_m_41_1_109',
  'A security architect wants to attach an existing IAM permission boundary to a new IAM role to restrict its maximum permissions. Order the steps to perform this attachment.',
  'ordering',
  '["Create or select the IAM role to which the boundary will be attached.","Verify the effective permissions of the IAM role.","Select the existing IAM policy that defines the permission boundary.","Attach the selected policy as a permission boundary to the IAM role."]'::json,
  '{0,2,3,1}',
  'To attach an existing IAM permission boundary to a new IAM role, the first step is to create or select the IAM role to which the boundary will be attached (Option A). Next, select the existing IAM policy that defines the permission boundary (Option C) from your list of IAM policies. Then, attach the selected policy as a permission boundary to the IAM role (Option D) in the IAM console. Finally, verify the effective permissions of the IAM role (Option B) to ensure the permission boundary is correctly restricting access.',
  NOW(),
  'quiz_domain41_8',
